  | "INTEGRATION_RECEIPT_MISMATCH"
  | "INTEGRATION_RECEIPT_TREE_MISMATCH"
  | "INTEGRATION_RECEIPT_DEVICE_MISMATCH"
  | "CANDIDATE_NOT_PINNED"
  | "CANDIDATE_CHANGED"
  | "VERIFICATION_NOT_STARTED"
  | "MERGE_NOT_PERMITTED";

