import { describe, expect, it } from "vitest";
import { applyEvent, emptyState, QueueRuleViolation, type BranchQueueState } from "./reducer.js";
import { applyEvents } from "./test/apply-events.js";
import type { QueueEvent } from "./events.js";

/** Probes for PR #316: cancel on every state a draft-withdrawal can meet. */

let seq = 0;
function ev<T extends Omit<QueueEvent, "sequence" | "idempotencyKey" | "at">>(body: T, key?: string): QueueEvent {
  seq += 1;
  return {
    sequence: seq,
    idempotencyKey: key ?? `probe${seq}`,
    at: new Date(Date.UTC(2026, 7, 1, 12, 0, seq % 60)).toISOString(),
    ...body,
  } as QueueEvent;
}

function base(): BranchQueueState {
  return emptyState("qk", "1315419165", "refs/heads/main");
}

const H = "h".repeat(40);
const B = "b".repeat(40);
const C = "c".repeat(40);
const T = "t".repeat(40);

function upTo(
  stop: "offered" | "claimed" | "prepared" | "assigned" | "running" | "requested",
  entryId = "e1",
  attemptId = "a1",
): QueueEvent[] {
  const all: Array<[string, QueueEvent]> = [
    [
      "offered",
      ev({
        type: "QueueRequested",
        entryId,
        pullRequestNumber: 7,
        sponsorPrincipalId: "alice",
        sponsorGithubUserId: "264261678",
        headSha: H,
      }),
    ],
    [
      "offered",
      ev({ type: "ReadinessEvaluated", entryId, ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }),
    ],
    [
      "offered",
      ev({ type: "TurnOffered", entryId, attemptId, offerDeadline: "2026-08-01T12:30:00.000Z", decisionDigest: "sha256:dec" }),
    ],
    ["claimed", ev({ type: "OfferClaimed", attemptId, executionMode: "device", deviceId: "d1" })],
    [
      "prepared",
      ev({
        type: "CandidatePrepared",
        attemptId,
        baseSha: B,
        headSha: H,
        candidateSha: C,
        candidateTree: T,
        policyDigest: "sha256:pol",
        runner: "dagger",
      }),
    ],
    [
      "assigned",
      ev({ type: "AssignmentIssued", attemptId, assignmentDigest: "sha256:asg", executionDeadline: "2026-08-01T13:00:00.000Z" }),
    ],
    ["running", ev({ type: "HeartbeatReceived", attemptId })],
    ["requested", ev({ type: "MergeRequested", attemptId })],
  ];
  const order = ["offered", "claimed", "prepared", "assigned", "running", "requested"];
  const limit = order.indexOf(stop);
  return all.filter(([phase]) => order.indexOf(phase) <= limit).map(([, event]) => event);
}

const cancel = (entryId = "e1") =>
  ev({ type: "EntryCancelled", entryId, actorPrincipalId: "github", reason: "the pull request is a draft" });

describe("PROBE: draft withdrawal cancel against every entry state", () => {
  it("cancel on ReconnectGrace (live attempt, NOT in HOLDING) terminates the attempt", () => {
    const running = applyEvents(base(), upTo("running"));
    const grace = applyEvent(running, ev({ type: "HeartbeatLost", attemptId: "a1", graceUntil: "2026-08-01T12:20:00.000Z" }));
    expect(grace.entries.get("e1")!.state).toBe("ReconnectGrace");
    expect(grace.activeAttemptId).toBe("a1");

    const after = applyEvent(grace, cancel());
    // The draft path cancels here because ReconnectGrace is not in HOLDING.
    expect(after.entries.get("e1")!.state).toBe("Cancelled");
    expect(after.attempts.get("a1")!.outcome).toBe("ADMIN_CANCELLED");
    expect(after.activeAttemptId).toBeNull();
  });

  it("cancel on Reconciling (merge outcome unknown, NOT in HOLDING) is refused", () => {
    // A MergeRequested attempt whose outcome is unknown needs verification etc.
    // Walk: offered..running then receipt/verify/intent/requested.
    const requested = applyEvents(base(), [
      ...upTo("running"),
      ev({ type: "ReceiptSubmitted", attemptId: "a1", receiptDigest: "sha256:rcpt" }),
      ev({ type: "VerificationStarted", attemptId: "a1", nonce: "n1" }),
      ev({ type: "VerificationCompleted", attemptId: "a1", nonce: "n1", accepted: true, resultDigest: "sha256:res" }),
      ev({ type: "MergeIntentCreated", attemptId: "a1", intentDigest: "sha256:intent" }),
      ev({ type: "MergeRequested", attemptId: "a1" }),
    ]);
    const reconciling = applyEvent(requested, ev({ type: "MergeOutcomeUnknown", attemptId: "a1", detail: "timeout" }));
