    expect(() => applyEvent(reconciling, cancel())).toThrow(QueueRuleViolation);
    expect(() => applyEvent(reconciling, cancel())).toThrow("cannot cancel while a merge outcome is unknown");
  });

  it("cancel on an already-Cancelled entry is a no-op (returns the same state)", () => {
    const placed = applyEvents(base(), [
      ev({
        type: "QueueRequested",
        entryId: "e1",
        pullRequestNumber: 7,
        sponsorPrincipalId: "alice",
