    expect(again).toBe(cancelled); // same reference: a no-op
  });

  it("cancel on Requested / Ready / Blocked / Deferred / NeedsRepair", () => {
    const requested = applyEvents(base(), [
      ev({
        type: "QueueRequested",
        entryId: "e1",
        pullRequestNumber: 7,
        sponsorPrincipalId: "alice",
        sponsorGithubUserId: "264261678",
        headSha: H,
      }),
    ]);
    expect(applyEvent(requested, cancel()).entries.get("e1")!.state).toBe("Cancelled");

    const ready = applyEvent(
      requested,
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }),
    );
    expect(ready.entries.get("e1")!.state).toBe("Ready");
    expect(applyEvent(ready, cancel()).entries.get("e1")!.state).toBe("Cancelled");

    const blocked = applyEvent(
      requested,
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: false, schedulerEligible: false, primaryReason: "PR_DRAFT", secondaryReasons: [] }),
    );
    expect(blocked.entries.get("e1")!.state).toBe("Blocked");
    expect(applyEvent(blocked, cancel()).entries.get("e1")!.state).toBe("Cancelled");

    // Deferred: offer expires.
    const offered = applyEvents(base(), upTo("offered"));
    const deferred = applyEvent(offered, ev({ type: "TurnOfferExpired", attemptId: "a1" }));
    expect(deferred.entries.get("e1")!.state).toBe("Deferred");
    expect(applyEvent(deferred, cancel()).entries.get("e1")!.state).toBe("Cancelled");
  });

  it("QueueRequested with resetOrdinal rebuilds a Cancelled entry as Requested and schedulable after readiness", () => {
    const placed = applyEvents(base(), [
      ev({
        type: "QueueRequested",
        entryId: "e1",
        pullRequestNumber: 7,
        sponsorPrincipalId: "alice",
        sponsorGithubUserId: "264261678",
        headSha: H,
      }),
    ]);
    const cancelled = applyEvent(placed, cancel());
    const rebuilt = applyEvent(
      cancelled,
      ev({
        type: "QueueRequested",
        entryId: "e1",
        pullRequestNumber: 7,
        sponsorPrincipalId: "alice",
        sponsorGithubUserId: "264261678",
        headSha: H,
        resetOrdinal: true,
      }),
    );
    expect(rebuilt.entries.get("e1")!.state).toBe("Requested");
    expect(rebuilt.entries.get("e1")!.schedulerEligible).toBe(false);
    expect(rebuilt.entries.get("e1")!.primaryReason).toBeNull();

    const evaluated = applyEvent(
      rebuilt,
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }),
    );
    expect(evaluated.entries.get("e1")!.state).toBe("Ready");
  });

  it("a ReadinessEvaluated deduplicated by key leaves the rebuilt entry Requested forever", () => {
    // The wedge: the readiness key is `authorize:ready:entry:head:bucket:decision`.
    // Reuse the SAME key after the rebuild and the evaluation is a no-op.
    const placed = applyEvents(base(), [
      ev({
        type: "QueueRequested",
        entryId: "e1",
        pullRequestNumber: 7,
        sponsorPrincipalId: "alice",
        sponsorGithubUserId: "264261678",
        headSha: H,
      }),
      ev(
        { type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] },
        "authorize:ready:e1:HEAD:100:true:true:",
      ),
    ]);
    expect(placed.entries.get("e1")!.state).toBe("Ready");

