    ["offered", ev({ type: "TurnOffered", entryId, attemptId, offerDeadline: "2026-08-01T12:30:00.000Z", decisionDigest: "sha256:dec" })],
    ["claimed", ev({ type: "OfferClaimed", attemptId, executionMode: "device", deviceId: "d1" })],
    ["prepared", ev({ type: "CandidatePrepared", attemptId, baseSha: B, headSha: H, candidateSha: C, candidateTree: T, policyDigest: "sha256:pol", runner: "dagger" })],
    ["assigned", ev({ type: "AssignmentIssued", attemptId, assignmentDigest: "sha256:asg", executionDeadline: "2026-08-01T13:00:00.000Z" })],
    ["running", ev({ type: "HeartbeatReceived", attemptId })],
    ["requested", ev({ type: "ReceiptSubmitted", attemptId, receiptDigest: "sha256:rcpt" })],
    ["requested", ev({ type: "VerificationStarted", attemptId, nonce: "n1" })],
    ["requested", ev({ type: "VerificationCompleted", attemptId, nonce: "n1", accepted: true, resultDigest: "sha256:res" })],
