    const placed = applyEvents(base(), [
      ev({ type: "QueueRequested", entryId: "e1", pullRequestNumber: 7, sponsorPrincipalId: "alice", sponsorGithubUserId: "1", headSha: H }, "authorize:request:e1"),
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }, readyKey),
    ]);
    expect(placed.entries.get("e1")!.state).toBe("Ready");

    // Draft withdraws it (no readiness write), then ready_for_review rebuilds it.
    const cancelled = applyEvent(placed, cancel());
    const rebuilt = applyEvent(
      cancelled,
      ev({ type: "QueueRequested", entryId: "e1", pullRequestNumber: 7, sponsorPrincipalId: "alice", sponsorGithubUserId: "1", headSha: H, resetOrdinal: true } as never, "authorize:request:e1:again:1"),
    );
    expect(rebuilt.entries.get("e1")!.state).toBe("Requested");

    // Same minute, same head, same decision: the readiness key is already applied.
    const deduped = applyEvent(
      rebuilt,
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }, readyKey),
    );
