  const order = ["offered", "claimed", "prepared", "assigned", "running", "requested"];
  const limit = order.indexOf(stop);
  return all.filter(([phase]) => order.indexOf(phase) <= limit).map(([, event]) => event);
}

const cancel = (entryId = "e1") =>
  ev({ type: "EntryCancelled", entryId, actorPrincipalId: "github", reason: "the pull request is a draft; it rejoins when marked ready" });

describe("PR316 probes: cancel against every state the draft path can meet", () => {
  it("cancel on ReconnectGrace terminates the live attempt (NOT left alone as the PR comment claims)", () => {
    const running = applyEvents(base(), upTo("running"));
    const grace = applyEvent(running, ev({ type: "HeartbeatLost", attemptId: "a1", graceUntil: "2026-08-01T12:05:00.000Z" }));
    expect(grace.entries.get("e1")!.state).toBe("ReconnectGrace");
    expect(grace.entries.get("e1")!.currentAttemptId).toBe("a1");
    expect(grace.attempts.get("a1")!.outcome).toBeNull();

    const after = applyEvent(grace, cancel());
    expect(after.entries.get("e1")!.state).toBe("Cancelled");
    expect(after.attempts.get("a1")!.outcome).toBe("ADMIN_CANCELLED");
    expect(after.activeAttemptId).toBeNull();
  });

  it("cancel on Reconciling is rejected: cannot cancel while a merge outcome is unknown", () => {
    const merging = applyEvents(base(), upTo("requested"));
    const reconciling = applyEvent(merging, ev({ type: "MergeOutcomeUnknown", attemptId: "a1", detail: "timeout" }));
    expect(reconciling.entries.get("e1")!.state).toBe("Reconciling");
    expect(reconciling.attempts.get("a1")!.outcomeUnknown).toBe(true);

    expect(() => applyEvent(reconciling, cancel())).toThrow(QueueRuleViolation);
    expect(() => applyEvent(reconciling, cancel())).toThrow("cannot cancel while a merge outcome is unknown");
  });

  it("cancel on an already-Cancelled entry is a no-op, not an error", () => {
    const ready = applyEvents(base(), upTo("offered").slice(0, 2));
    const cancelled = applyEvent(ready, cancel());
    expect(cancelled.entries.get("e1")!.state).toBe("Cancelled");
    const again = applyEvent(cancelled, cancel());
    expect(again).toBe(cancelled); // same reference: reducer signalled no-op
  });

  it("cancel on Requested / Ready / Blocked / Deferred / NeedsRepair each lands in Cancelled", () => {
    // Requested
    const requested = applyEvents(base(), upTo("offered").slice(0, 1));
    expect(applyEvent(requested, cancel()).entries.get("e1")!.state).toBe("Cancelled");

    // Ready
    const ready = applyEvents(base(), upTo("offered").slice(0, 2));
    expect(ready.entries.get("e1")!.state).toBe("Ready");
    expect(applyEvent(ready, cancel()).entries.get("e1")!.state).toBe("Cancelled");

    // Blocked
    const blocked = applyEvents(base(), [
      upTo("offered")[0]!,
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: false, schedulerEligible: false, primaryReason: "PR_DRAFT", secondaryReasons: [] }),
    ]);
    expect(blocked.entries.get("e1")!.state).toBe("Blocked");
    expect(applyEvent(blocked, cancel()).entries.get("e1")!.state).toBe("Cancelled");

    // Deferred: offer, claim, then supersede the attempt (entry defers)
    const claimed = applyEvents(base(), upTo("claimed"));
    const deferred = applyEvent(claimed, ev({ type: "AttemptTerminated", attemptId: "a1", outcome: "SUPERSEDED" } as never));
    // If AttemptTerminated is not the right event name this throws; printed for the record.
    expect(["Deferred", "Blocked", "NeedsRepair"]).toContain(deferred.entries.get("e1")!.state);
    expect(applyEvent(deferred, cancel()).entries.get("e1")!.state).toBe("Cancelled");
  });

  it("a rebuilt (re-joined) entry dedupes a readiness evaluation keyed the same as before withdrawal", () => {
    // Entry evaluated ready with decision key K at minute bucket M.
    const readyKey = "authorize:ready:e1:" + H + ":100:true:true:";
    const placed = applyEvents(base(), [
      ev({ type: "QueueRequested", entryId: "e1", pullRequestNumber: 7, sponsorPrincipalId: "alice", sponsorGithubUserId: "1", headSha: H }, "authorize:request:e1"),
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }, readyKey),
    ]);
    expect(placed.entries.get("e1")!.state).toBe("Ready");

    // Draft withdraws it (no readiness write), then ready_for_review rebuilds it.
    const cancelled = applyEvent(placed, cancel());
    const rebuilt = applyEvent(
      cancelled,
      ev({ type: "QueueRequested", entryId: "e1", pullRequestNumber: 7, sponsorPrincipalId: "alice", sponsorGithubUserId: "1", headSha: H, resetOrdinal: true } as never, "authorize:request:e1:again:1"),
    );
    expect(rebuilt.entries.get("e1")!.state).toBe("Requested");

    // Same minute, same head, same decision: the readiness key is already applied.
    const deduped = applyEvent(
      rebuilt,
      ev({ type: "ReadinessEvaluated", entryId: "e1", ready: true, schedulerEligible: true, primaryReason: null, secondaryReasons: [] }, readyKey),
    );
    expect(deduped).toBe(rebuilt); // no-op
    expect(deduped.entries.get("e1")!.state).toBe("Requested"); // stuck: not Ready, never schedulable
    expect(deduped.entries.get("e1")!.schedulerEligible).toBe(false);
    expect(deduped.entries.get("e1")!.primaryReason).toBeNull();
  });
});
"
