import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { testD1 } from "../../test/d1.js";
import { acceptProof } from "../../test/proof.js";
import type { QueueRouteEnv } from "./routes.js";
import { loadQueueState } from "./queue-state.js";
import type { D1Like } from "./projection.js";

// Temporary adversarial probes for PR #316 verification. Not for merge.

vi.mock("./BranchQueue.js", () => ({ BranchQueue: class {} }));
vi.mock("../github-app.js", async (original) => ({
  ...(await original<Record<string, unknown>>()),
  installationToken: async () => "installation-token",
}));
const { queueFromPullRequest } = await import("../index.js");

const open: Array<{ close(): void }> = [];
let raw: import("better-sqlite3").Database;

const REPO = "1315419165";
const REF = "refs/heads/main";
const HEAD_A = "5".repeat(40);
const HEAD_B = "6".repeat(40);

function env(): QueueRouteEnv {
  const t = testD1();
  open.push(t);
  raw = t.raw;
  raw
    .prepare("INSERT INTO organizations (id, github_org_id, github_login, installation_id) VALUES (?, ?, ?, ?)")
    .run("org_1", "1", "acme", "9001");
  raw
    .prepare(
      "INSERT INTO queue_projects (id, organization_id, github_repository_id, base_ref, enabled, activation_state) VALUES (?, ?, ?, ?, 1, 'enforced')",
    )
    .run("qp_1", "org_1", REPO, REF);
  raw
    .prepare(
      "INSERT INTO projects (id, organization_id, github_repository_id, github_name, enabled) VALUES (?, ?, ?, ?, 1)",
    )
    .run("proj_1", "org_1", REPO, "acme/repo");
  raw
    .prepare(
      "INSERT INTO principals (id, organization_id, github_user_id, github_login, activated_at) VALUES (?, ?, ?, ?, datetime('now'))",
    )
    .run("alice", "org_1", "1", "alice");
  return { DB: t.db, PUBLIC_ORIGIN: "https://thwip.test" } as unknown as QueueRouteEnv;
}

beforeEach(() => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: string | URL | Request) =>
      String(input).includes("/check-runs") ? Response.json({ check_runs: [] }) : Response.json([]),
    ),
  );
});

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllGlobals();
  while (open.length > 0) open.pop()!.close();
});

function pr(action: string, number: number, headSha: string, draft = false) {
  return {
    action,
    pull_request: {
      number,
      draft,
      state: "open",
      base: { ref: "main", repo: { id: Number(REPO) } },
      head: { sha: headSha },
      user: { id: 1, login: "alice", type: "User" },
    },
  };
}

async function entry(e: QueueRouteEnv, number: number) {
  const { store } = await loadQueueState(e.DB as unknown as D1Like, REPO, REF);
  return store.state().entries.get(`entry_${REPO}_${number}`);
}

describe("PR316 probe: the same-minute rejoin wedge", () => {
  it("rejoining in the same minute with an unchanged decision leaves the entry Requested forever", async () => {
    vi.useFakeTimers({ now: Date.UTC(2026, 7, 1, 12, 0, 0) });
    const e = env();

    // PR 120 takes the lane.
    acceptProof(raw, REPO, HEAD_A);
    await queueFromPullRequest(e as never, pr("opened", 120, HEAD_A));
    expect((await entry(e, 120))?.state).toBe("Active");

    // PR 121 is ready but the lane is busy: it waits, decision "true:true:" written this minute.
    acceptProof(raw, REPO, HEAD_B);
    await queueFromPullRequest(e as never, pr("opened", 121, HEAD_B));
    const placedB = await entry(e, 121);
    expect(placedB?.state).toBe("Ready");
    expect(placedB?.schedulerEligible).toBe(true);

    // Marked draft: withdrawn. No readiness event is written.
    await queueFromPullRequest(e as never, pr("converted_to_draft", 121, HEAD_B, true));
    expect((await entry(e, 121))?.state).toBe("Cancelled");

    // Marked ready again inside the same minute bucket, same head, same decision.
    const result = await queueFromPullRequest(e as never, pr("ready_for_review", 121, HEAD_B));
    expect(result.handled).toBe(true);

    const rejoined = await entry(e, 121);
    // THE WEDGE: the readiness evaluation was deduplicated against the one from
    // before the withdrawal, so the rebuilt entry is never made Ready.
    console.log("rejoined state:", rejoined?.state, "eligible:", rejoined?.schedulerEligible, "reason:", rejoined?.primaryReason);

    // PR 120 closes; the settle tick offers the lane to whoever is eligible.
    await queueFromPullRequest(e as never, { ...pr("closed", 120, HEAD_A), pull_request: { ...pr("closed", 120, HEAD_A).pull_request, state: "closed" } });
    expect((await entry(e, 120))?.state).toBe("Cancelled");

    const wedged = await entry(e, 121);
    console.log("after lane freed:", wedged?.state, "eligible:", wedged?.schedulerEligible);
    const { store } = await loadQueueState(e.DB as unknown as D1Like, REPO, REF);
    console.log("activeAttemptId after close:", store.state().activeAttemptId);

    // A synchronize in a later minute re-evaluates and recovers.
    vi.setSystemTime(Date.UTC(2026, 7, 1, 12, 2, 0));
    await queueFromPullRequest(e as never, pr("synchronize", 121, HEAD_B));
    console.log("after later-minute synchronize:", (await entry(e, 121))?.state);
  });
});

